/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

/**
 * An error seen by the collector, as the grouping in issues needs it.
 *
 * @param source code of the observed source
 * @param ts epoch milliseconds
 * @param level {@code ERROR} or {@code FATAL}
 * @param type exception type ({@code java.lang.IllegalStateException}, {@code TypeError}...)
 * @param message exception message (or the log message without exception message)
 * @param stack stack trace, if any
 * @param traceId trace of the event, if any
 * @param fingerprint fingerprint forced by the client (attribute {@code fingerprint}), if any
 * @param release version of the source, if known
 * @param context who and where (user, tenant, session, route...)
 */
public record ErrorEvent(String source, long ts, String level, String type, String message,
    String stack, String traceId, String fingerprint, String release, EventContext context) {

  /** The event with the empty fields of its context taken from {@code other}. */
  public ErrorEvent withContext(final EventContext other) {
    return null == other ? this : new ErrorEvent(source, ts, level, type, message, stack, traceId,
        fingerprint, release, (null == context ? EventContext.EMPTY : context).orElse(other));
  }
}
